import{_ as t,c as e,o as r,a0 as o}from"./chunks/framework.C1J0Vcxi.js";const f=JSON.parse('{"title":"第三十一周：StarryOS AIA 中断驱动集成与 K3 COM260 板级支持（UFS/小车调试）","description":"","frontmatter":{},"headers":[],"relativePath":"周报-Oveln/2026-08-02-周报三十一.md","filePath":"周报-Oveln/2026-08-02-周报三十一.md"}'),i={name:"周报-Oveln/2026-08-02-周报三十一.md"};function l(d,a,s,n,c,h){return r(),e("div",null,[...a[0]||(a[0]=[o('<h1 id="第三十一周-starryos-aia-中断驱动集成与-k3-com260-板级支持-ufs-小车调试" tabindex="-1">第三十一周：StarryOS AIA 中断驱动集成与 K3 COM260 板级支持（UFS/小车调试） <a class="header-anchor" href="#第三十一周-starryos-aia-中断驱动集成与-k3-com260-板级支持-ufs-小车调试" aria-label="Permalink to &quot;第三十一周：StarryOS AIA 中断驱动集成与 K3 COM260 板级支持（UFS/小车调试）&quot;">​</a></h1><h2 id="一、本周完成事项" tabindex="-1">一、本周完成事项 <a class="header-anchor" href="#一、本周完成事项" aria-label="Permalink to &quot;一、本周完成事项&quot;">​</a></h2><h3 id="_1-starryos-tgoskits-feat-riscv-aia-分支-aia-相关驱动开发" tabindex="-1">1. StarryOS（tgoskits）<code>feat/riscv-aia</code> 分支：AIA 相关驱动开发 <a class="header-anchor" href="#_1-starryos-tgoskits-feat-riscv-aia-分支-aia-相关驱动开发" aria-label="Permalink to &quot;1. StarryOS（tgoskits）`feat/riscv-aia` 分支：AIA 相关驱动开发&quot;">​</a></h3><p>完成 RISC-V 高级中断架构（AIA）驱动从调研到可用，QEMU 与 K3 测试均通过，可正常使用。相关提交：</p><ul><li><code>fcca4fc47</code> <strong>集成 IMSIC + APLIC 驱动</strong>，修复 virtio INTx 中断风暴</li><li><code>da4df1dcf</code> <code>irq_set_affinity</code> 支持 APLIC/IMSIC domain</li><li><code>a0c240578</code> APLIC trigger 改为从 FDT 提取 + fallback LevelHigh，修复 virtio-blk INTx 不触发</li><li><code>062027bf9</code> APLIC <code>stopei</code> 读后必须写回清 pending，否则 IRQ 永不清除、反复 trap</li><li><code>56cd7e15d</code> 代码质量订正：删死代码 + 提取纯函数 + 补单测</li></ul><h3 id="_2-ufs-驱动完善-feat-k3-board-support-分支" tabindex="-1">2. UFS 驱动完善（<code>feat/k3-board-support</code> 分支） <a class="header-anchor" href="#_2-ufs-驱动完善-feat-k3-board-support-分支" aria-label="Permalink to &quot;2. UFS 驱动完善（`feat/k3-board-support` 分支）&quot;">​</a></h3><ul><li><strong>修复 UFS 只能跑低速的问题</strong>：先前 UFS 驱动测试发现只能运行在低速状态，本周定位并修复，当前可跑在<strong>最高速度</strong>；</li><li>修复 transfer timeout 后 doorbell slot 卡死问题（<code>5285f9136</code>，可恢复 wedged slot）；</li><li>本周另有约 600 行 UFS 增量改动（<code>init.rs</code>/<code>regs.rs</code>/<code>mod.rs</code>）待整理提交，方向为传输路径与寄存器语义梳理。</li></ul><h2 id="二、会议纪要" tabindex="-1">二、会议纪要 <a class="header-anchor" href="#二、会议纪要" aria-label="Permalink to &quot;二、会议纪要&quot;">​</a></h2><h3 id="_2-1-与向勇老师交流-2026-08-02" tabindex="-1">2.1 与向勇老师交流（2026-08-02） <a class="header-anchor" href="#_2-1-与向勇老师交流-2026-08-02" aria-label="Permalink to &quot;2.1 与向勇老师交流（2026-08-02）&quot;">​</a></h3><ul><li><strong>过程记录要求</strong>：老师强调项目推进过程要有记录、可追溯，多人协作必须留下文档，认为这是提高效率的重要方法；</li><li><strong>分工调整</strong>：黄佳铭暂时不参与本项目，由我和周雨继续推进后续工作；</li><li><strong>条件支持</strong>：老师会为后续推进提供相应条件；</li><li><strong>目标期望</strong>：希望最终能取得比赛获奖、毕业设计或论文发表的好结果；</li><li><strong>记录要求</strong>：本次讨论内容需写入周报留存。</li></ul><h2 id="三、小车串口方案" tabindex="-1">三、小车串口方案 <a class="header-anchor" href="#三、小车串口方案" aria-label="Permalink to &quot;三、小车串口方案&quot;">​</a></h2><ul><li><strong>问题</strong>：小车与 K3 经三个 USB 接口（2×UART + 1×摄像头）连接；X100 大核域可用 USB 总线访问串口，但 RT24 域无法访问 USB 总线，需确认外设物理串口连接方案；</li><li><strong>后续</strong>：按手册确认具体连线方式。</li></ul><h2 id="三、存在问题-待办" tabindex="-1">三、存在问题 / 待办 <a class="header-anchor" href="#三、存在问题-待办" aria-label="Permalink to &quot;三、存在问题 / 待办&quot;">​</a></h2><ul><li><strong>StarryOS 在 K3 上的驱动仍缺失</strong>：摄像头、网卡驱动尚未开发；</li><li>小车底盘控制板固件/连线方式待按手册确认（若 USB 转串口方案不通，可能需刷底盘控制板固件）。</li></ul><h2 id="四、下周计划" tabindex="-1">四、下周计划 <a class="header-anchor" href="#四、下周计划" aria-label="Permalink to &quot;四、下周计划&quot;">​</a></h2><ul><li>按手册确认小车物理串口连线（含电压核对），推进 RT24 域驱动小车联调；</li><li>评估并启动 StarryOS 侧缺失驱动（摄像头 / 网卡）的开发；</li><li>遗留问题解决后照常推进，保持过程记录与文档可追溯。</li></ul><h2 id="五、相关分支-提交位置" tabindex="-1">五、相关分支 / 提交位置 <a class="header-anchor" href="#五、相关分支-提交位置" aria-label="Permalink to &quot;五、相关分支 / 提交位置&quot;">​</a></h2><table tabindex="0"><thead><tr><th>仓库</th><th>分支</th><th>说明</th></tr></thead><tbody><tr><td>tgoskits</td><td><code>feat/riscv-aia</code></td><td>AIA（IMSIC/APLIC）驱动，QEMU + K3 通过</td></tr><tr><td>tgoskits</td><td><code>feat/k3-board-support</code></td><td>K3 COM260 板级（UART/SDHCI/GMAC/UFS 等）</td></tr></tbody></table>',18)])])}const S=t(i,[["render",l]]);export{f as __pageData,S as default};
